def test_ineligible_booking_reports_ordered_reasons_and_changes_nothing():
    subject = booking_subject()
    subject.update(
        consents=[{"version": "v1", "signed_on": "2023-12-01"}],
        flags=["DO_NOT_ENROLL"],
        labs={"A": 4},
    )
    protocol = booking_protocol()
    capacity = {date(2024, 1, 1): 1}
    original_subject = deepcopy(subject)
    original_protocol = deepcopy(protocol)

    with pytest.raises(ValueError) as caught:
        book_subject_visits(
            subject, protocol, **booking_kwargs(capacity)
        )

    message = str(caught.value)
    assert message.startswith("INELIGIBLE:")
    assert message.index("CONSENT_MISSING") < message.index("CONSENT_VERSION")
    assert message.index("CONSENT_VERSION") < message.index("EXCLUSION_DO_NOT_ENROLL")
    assert message.index("EXCLUSION_DO_NOT_ENROLL") < message.index("LAB_A_HIGH")
    assert capacity == {date(2024, 1, 1): 1}
    assert subject == original_subject
    assert protocol == original_protocol


